-- ================================================================
-- NU-FAST (FAST-NUCES) FULL SEED — generated from
--   src/backend/data/Universities/NU-FAST/nu_fast_requirements_data_verified.json
--   src/backend/data/Universities/NU-FAST/nu_fast_student_profile_verified.json
-- Import via phpMyAdmin → Import tab (file is large; do not paste into SQL tab).
--
-- * Reuses the existing HEC master row for "National University of Computer and Emerging Sciences" when present
--   (matched on normalized_name, then on name) so no duplicate university is created.
-- * Idempotent: re-running deletes this university's seeded rows first, then re-inserts.
-- * Preserves: universities.id, universities.owner_uid, campuses.campus_admin_uid,
--   Student_signup accounts (nothing here touches them).
-- * Render-critical: campus_programs.status='published', campus_hostels.status='live'.
-- * detail JSON keeps the original scraped keys AND adds the keys the Programs tab
--   reads (fees[] / eligibility[] / entryTest / interviewOn / merit) — derived from the
--   same values, no invented data.
-- ================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ── STEP 0: resolve (or create) the university row ────────────────────────
-- FAST appears in the HEC master list under several spellings
-- ("… and …", "… & …", "FAST – NU"). Match all of them before creating a row,
-- otherwise this seed would create a second university and duplicate campuses.
SET @uni_id = COALESCE(
  (SELECT id FROM universities WHERE normalized_name = 'national university of computer and emerging sciences' LIMIT 1),
  (SELECT id FROM universities WHERE name = 'National University of Computer and Emerging Sciences' LIMIT 1),
  (SELECT id FROM universities WHERE oric_domain = '@nu.edu.pk' ORDER BY is_hec_listed DESC, id LIMIT 1),
  (SELECT id FROM universities WHERE domain = 'nu.edu.pk' ORDER BY is_hec_listed DESC, id LIMIT 1),
  (SELECT id FROM universities
    WHERE (name LIKE '%Computer%Emerging Sciences%' OR name LIKE '%FAST%NU%')
      AND name NOT LIKE '%CECOS%' AND name NOT LIKE '%Commecs%' AND name NOT LIKE '%Institute%'
    ORDER BY is_hec_listed DESC, hec_rank IS NULL, id LIMIT 1),
  '6b0f4f2e-9d47-4f0c-9f3a-9d5c1a70f0a1'
);

INSERT INTO universities
  (id, owner_uid, name, normalized_name, hec_rank, university_type, oric_domain, domain,
   focal_person_name, focal_person_email, campuses_text, campus_count, is_hec_listed, status,
   tagline, hero_subtitle, about_title, about_text, description, mission, vision,
   ranking, ranking_label, students, employment_rate, partner_countries, total_campuses,
   established_year, website, email, phone, city, address, logo_url, banner_url,
   last_synced_at, created_at, updated_at)
VALUES
  (@uni_id, NULL, 'National University of Computer and Emerging Sciences', 'national university of computer and emerging sciences', 5, 'Private',
   '@nu.edu.pk', 'nu.edu.pk',
   NULL, NULL,
   'Chiniot-Faisalabad; Islamabad; Karachi; Lahore; Multan; Peshawar', 6, 1, 'approved',
   'Premier University of Pakistan', 'Five modern Campuses in Major Cities Across Country',
   'About National University of Computer and Emerging Sciences', 'The National University of Computer & Emerging Sciences has the honor of being the first multi-campus private sector university set up under the Federal Charter granted by Ordinance No.XXIII of 2000, dated July 01, 2000. The University started with an impressive advantage in that, thanks to the selfless, ceaseless and imaginative efforts of the Foundation FAST, it inherited four first rate computer science institutes located at Karachi, Lahore, Islamabad and Peshawar, in spacious buildings and prestigious settings. These institutes, individually as well as collectively, have established leadership position due to the splendid vision of an enlightened management and tireless efforts of a highly qualified faculty. Over the years FAST has become the hallmark of excellence in academic arena, domestic market and international community.',
   'The National University of Computer & Emerging Sciences has the honor of being the first multi-campus private sector university set up under the Federal Charter granted by Ordinance No.XXIII of 2000, dated July 01, 2000. The University started with an impressive advantage in that, thanks to the selfless, ceaseless and imaginative efforts of the Foundation FAST, it inherited four first rate computer science institutes located at Karachi, Lahore, Islamabad and Peshawar, in spacious buildings and prestigious settings. These institutes, individually as well as collectively, have established leadership position due to the splendid vision of an enlightened management and tireless efforts of a highly qualified faculty. Over the years FAST has become the hallmark of excellence in academic arena, domestic market and international community.

HEC Recognized: Yes. Rankings: ranked institutes of the world; rank in the relevant NTS subject test; Ranked Programs; QS WUR Ranking By Subject 2026: #651-700. Accreditations: Accreditation; accredited program (BS AI) of study designed to prepare graduates as computing professionals; accredited program (BS CS)of study designed to prepare graduates as computing professionals; accredited program (BS CY) of study designed to prepare graduates as computing professionals; accredited program (BS DS) of study designed to; accredited program (BS SE)of study designed to prepare graduates as computing professionals. Students: Over 11,000 across all campuses. Faculty: Over 500 faculty members. Established: July 01, 2000. Career services: Office Top recruiters:  Notable alumni:  Student societies: FAST Data Science Society Events: https://khi.nu.edu.pk/students-societies-extracurricular-activities/ Apply online: http://admissions.nu.edu.pk/ Application fee: PKR 3,000 Fee basis: Semester (semester_fee); Annual (annual_fee = semester_fee x 2); Total degree cost (total_degree_cost) for full program duration. Miscellaneous fees: Additional Transcript Fee PKR 300; Campus Transfer Fee PKR 5000; Temporary Campus Transfer Fee PKR 2000; Degree Correction Fee PKR 2000; Semester Freeze Fee (within two weeks of start of classes) PKR 2000; Late Registration Fee / Freeze Fee / Course Withdrawal (after second week of start of classes) PKR 5000; Retake Sessional Exam Fee (per course) PKR 2000; Retake Final Exam Fee (per course/lab) PKR 2000; Paper Rechecking Fee (per course/lab) PKR 500; Issuance of Certificate/Letter Fee PKR 300; Applicant Admission Fee PKR 3000. Refund policy: admission fee Non-refundable; security deposit Refundable at the time of completion of degree or closing of admission; tuition fee Refunded in accordance with Higher Education Commission (HEC) guidelines; schedule Upto 10th day of commencement of classes: 100%; Upto 15th day of commencement of classes: 80%; Upto 20th day of commencement of classes: 60%; Upto 30th day of commencement of classes: 50%; 31st day onwards of commencement of classes: 0%. Refund note: Days are counted including working days and holidays. After declaration of FSc/A-Level/Equivalent result, admission stands cancelled if eligibility requirements are not met. Fee refund is calculated from the date of result announcement. Payment methods: Print challan form and visit nearest United Bank Limited or Faysal Bank branch for cash deposit (UBL: MCA A/C 344057508; Faysal Bank: FAST-ISD); Via bank account using Kuickpay payment gateway (voucher number: 0117032614082405; Rs 60 transaction fee per payment). KuickPay supported banks: Allied Bank; Askari Bank; Bank Al Habib; Bank Alfalah; Bank Islami; Bank of Punjab; Dubai Islamic Bank; Faysal Bank; First Women Bank; Habib Metro Bank; Habib Bank Limited; JS Bank; MCB Bank; NRSP Bank; MCB Islamic Bank; Meezan Bank; National Bank; SAMBA Bank; Soneri Bank; Summit Bank; UBL; Keenu App. KuickPay additional methods: Easy paisa; JazzCash. Social media: facebook: https://www.facebook.com/FastUniversityOfficial/; x: https://www.twitter.com/FastNuOfficial; youtube: https://www.youtube.com/channel/UC0s-RmNrTAizAAJoX7z5e2w. Admissions emails: admissions@nu.edu.pk; admissions.cfd@nu.edu.pk; admissions.isb@nu.edu.pk; admissions.khi@nu.edu.pk; admissions.lhr@nu.edu.pk; admissions.mtn@nu.edu.pk; admissions.pwr@nu.edu.pk; admissions.international@nu.edu.pk.', 'To identify and attract the most promising students from diverse communities, to shape them into visionary leaders and world-class professionals. To impart quality education to students, irrespective of their financial background, ethnicity, gender or religion to create an inclusive society. To promote research and scholarly activities to generate knowledge.', 'To produce world-class professionals, who are responsible citizens and good human beings.',
   '#651-700', 'QS WUR Ranking By Subject 2026',
   'Over 11,000 students across all campuses', NULL,
   NULL, '6',
   '2000', 'https://www.nu.edu.pk/',
   'info@nu.edu.pk', '+92-51-2855072', 'Islamabad',
   'FAST House, Rohtas Road, G-9/4, Islamabad - 44000', 'https://www.nu.edu.pk/Content/images/NU-logo.jpg', 'https://www.nu.edu.pk/Content/images/Slider/background.jpg',
   '2026-10-10T10:59:36.712Z', NOW(), NOW())
ON DUPLICATE KEY UPDATE
   name                    = VALUES(name),
   normalized_name         = COALESCE(NULLIF(normalized_name, ''), VALUES(normalized_name)),
   hec_rank                = VALUES(hec_rank),
   university_type         = VALUES(university_type),
   oric_domain             = VALUES(oric_domain),
   domain                  = VALUES(domain),
   campuses_text           = VALUES(campuses_text),
   campus_count            = VALUES(campus_count),
   is_hec_listed           = 1,
   status                  = 'approved',
   tagline                 = VALUES(tagline),
   hero_subtitle           = VALUES(hero_subtitle),
   about_title             = VALUES(about_title),
   about_text              = VALUES(about_text),
   description             = VALUES(description),
   mission                 = VALUES(mission),
   vision                  = VALUES(vision),
   ranking                 = VALUES(ranking),
   ranking_label           = VALUES(ranking_label),
   students                = VALUES(students),
   employment_rate         = VALUES(employment_rate),
   partner_countries       = VALUES(partner_countries),
   total_campuses          = VALUES(total_campuses),
   established_year        = VALUES(established_year),
   website                 = VALUES(website),
   email                   = VALUES(email),
   phone                   = VALUES(phone),
   city                    = VALUES(city),
   address                 = VALUES(address),
   logo_url                = VALUES(logo_url),
   banner_url              = VALUES(banner_url),
   updated_at              = NOW();

-- @uni_id may point at a row whose id differs from the fallback constant.
SET @uni_id = COALESCE(
  (SELECT id FROM universities WHERE id = @uni_id LIMIT 1),
  (SELECT id FROM universities WHERE normalized_name = 'national university of computer and emerging sciences' LIMIT 1),
  @uni_id
);

-- ── STEP 1: clear this university's seeded rows (campuses rows kept) ───────
-- PREFLIGHT (read-only): lists the row this seed writes to plus any other row
-- that also looks like FAST. More than one row here = duplicate university,
-- which is what makes the campus list show the same campuses twice.
SELECT id, name, normalized_name, oric_domain, owner_uid,
       (SELECT COUNT(*) FROM campuses c WHERE c.university_id = u.id)  AS campus_rows,
       (SELECT COUNT(*) FROM programs p WHERE p.university_id = u.id)  AS program_rows
FROM universities u
WHERE u.id = @uni_id
   OR u.normalized_name LIKE '%computer%emerging sciences%'
   OR u.name LIKE '%Computer%Emerging Sciences%'
   OR u.oric_domain = '@nu.edu.pk';

DELETE FROM campus_programs   WHERE campus_id IN (SELECT id FROM campuses WHERE university_id = @uni_id);
DELETE FROM campus_societies  WHERE campus_id IN (SELECT id FROM campuses WHERE university_id = @uni_id);
DELETE FROM campus_facilities WHERE campus_id IN (SELECT id FROM campuses WHERE university_id = @uni_id);
DELETE FROM campus_images     WHERE campus_id IN (SELECT id FROM campuses WHERE university_id = @uni_id);
DELETE FROM campus_hostels    WHERE campus_id IN (SELECT id FROM campuses WHERE university_id = @uni_id);
DELETE FROM programs          WHERE university_id = @uni_id;
DELETE FROM university_images WHERE university_id = @uni_id;
DELETE FROM university_profiles WHERE university_id = @uni_id;

-- ── STEP 2: university_profiles (1 row) ──────────────────────────────────
