-- ── STEP 3: campuses (6 rows) ─────────────────────────────────────────────
-- 3a: fold existing variant names onto the canonical spellings so the INSERT below
--     does not add a second row for the same campus (ids and campus_admin_uid stay).

UPDATE campuses SET name = 'Chiniot-Faisalabad' WHERE university_id = @uni_id AND (name LIKE 'Chiniot%' OR name LIKE 'Faisalabad%') AND name <> 'Chiniot-Faisalabad' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000001';
DELETE FROM campuses WHERE university_id = @uni_id AND name = 'Chiniot-Faisalabad' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000001' AND campus_admin_uid IS NULL;

UPDATE campuses SET name = 'Islamabad' WHERE university_id = @uni_id AND (name LIKE 'Islamabad%') AND name <> 'Islamabad' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000002';
DELETE FROM campuses WHERE university_id = @uni_id AND name = 'Islamabad' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000002' AND campus_admin_uid IS NULL;

UPDATE campuses SET name = 'Karachi' WHERE university_id = @uni_id AND (name LIKE 'Karachi%') AND name <> 'Karachi' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000003';
DELETE FROM campuses WHERE university_id = @uni_id AND name = 'Karachi' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000003' AND campus_admin_uid IS NULL;

UPDATE campuses SET name = 'Lahore' WHERE university_id = @uni_id AND (name LIKE 'Lahore%') AND name <> 'Lahore' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000004';
DELETE FROM campuses WHERE university_id = @uni_id AND name = 'Lahore' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000004' AND campus_admin_uid IS NULL;

UPDATE campuses SET name = 'Multan' WHERE university_id = @uni_id AND (name LIKE 'Multan%') AND name <> 'Multan' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000005';
DELETE FROM campuses WHERE university_id = @uni_id AND name = 'Multan' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000005' AND campus_admin_uid IS NULL;

UPDATE campuses SET name = 'Peshawar' WHERE university_id = @uni_id AND (name LIKE 'Peshawar%') AND name <> 'Peshawar' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000006';
DELETE FROM campuses WHERE university_id = @uni_id AND name = 'Peshawar' AND id <> '6b0f4f2e-9d47-4f0c-9f3a-000000000006' AND campus_admin_uid IS NULL;


